local _, ns = ...
local L = ns.L

-- Options/HelpPanes.lua: the FAQ and Support pages; English beside Locales/enUS.lua.
L["FAQ_CAPTION"] = "Common questions, and where things went."
L["FAQ_SEARCH"] = "Search questions"
L["FAQ_NONE"] = "No question matches."
L["FAQ_NOT_BOUND"] = "not bound"
L["FAQ_LFG_Q"] = "Where is my LFG (group finder) button?"
L["FAQ_LFG_A"] = "1.x had none, so it is off the micro menu. Click the eye on the minimap, use the side tabs of the social window's Who tab, or press the group finder key (%s). To bring the button back, uncheck \"%s\" under \"%s\"."
L["FAQ_LEGACY_Q"] = "Where is my Legacy button?"
L["FAQ_LEGACY_A"] = "1.x had none, so it is off the micro menu. Click its icon on the minimap. To bring the button back, uncheck \"%s\" under \"%s\". Any micro button can sit on the minimap: check it under \"%s\"."
L["FAQ_PROFESSIONS_Q"] = "Where is my professions button?"
L["FAQ_PROFESSIONS_A"] = "1.x had none, so it is off the micro menu. Open your professions from the spellbook, or press the professions key (%s). To bring the button back, uncheck \"%s\" under \"%s\"."
L["FAQ_COLLECTIONS_Q"] = "Where is my collections button?"
L["FAQ_COLLECTIONS_A"] = "1.x had none, so it is off the micro menu. Open your mounts, pets, toys and appearances from the \"%s\" tab at the foot of the spellbook, or press the collections key (%s). To bring the button back, uncheck \"%s\" under \"%s\"."
L["FAQ_QUICKJOIN_Q"] = "Where is the %s tab?"
L["FAQ_QUICKJOIN_A"] = "In the social window, open %s and then %s. The %s tab under the list swaps to it, and the %s tab swaps back."
L["FAQ_REAGENT_Q"] = "Where is my reagent bag?"
L["FAQ_REAGENT_A"] = "It is the small round bag between the key ring and your last bag, shown while the mouse is over your bags. To keep it in view, pick \"%s\", or \"%s\" for a slot like the other bags."
L["FAQ_TENBUTTONS_Q"] = "Why does my main bar show 10 buttons, or the wrong size?"
L["FAQ_TENBUTTONS_A"] = "The band follows Action Bar 1's settings in edit mode: \"%s\" and \"%s\". \"%s\" on the \"%s\" page gives 1.x's smaller buttons."
L["FAQ_GRYPHONS_Q"] = "How do I hide the gryphons?"
L["FAQ_GRYPHONS_A"] = "On the \"%s\" page, set \"%s\" or \"%s\" to \"%s\". In edit mode each gryphon is a piece of its own, to move or hide."
L["FAQ_XPBAR_Q"] = "Can I hide the experience bar or move it off the band?"
L["FAQ_XPBAR_A"] = "Yes, in edit mode. Click the experience or reputation bar: it can be dragged off the band, and its box has \"%s\"."
L["FAQ_SIZE_Q"] = "Why are the windows smaller than the game's? Can I make them bigger?"
L["FAQ_SIZE_A"] = "They are Classic Era's own sizes. Click the lock in a window's title bar and drag the grip in its corner, or size it in edit mode under \"%s\". The bars follow \"%s\" and the size in each bar's edit mode box."
L["FAQ_SCALE_Q"] = "Why did my interface get bigger?"
L["FAQ_SCALE_A"] = "Classic Era draws its interface larger than Forever. Picking the classic layout with Era's size sets the game's UI Scale to it, 90%% on most screens. Change it any time under %s in the game's Options (\"%s\")."
L["FAQ_SCALEBACK_Q"] = "How do I get my old interface size back?"
L["FAQ_SCALEBACK_A"] = "Press \"%s\" in the sidebar with \"%s\" checked: your size from before goes back with the options. Or set it under %s in the game's Options; uncheck \"%s\" for the game's automatic size."
L["FAQ_SCALEBACK_PIECE_A"] = "Set it under %s in the game's Options; uncheck \"%s\" for the game's automatic size."
L["FAQ_GLOW_Q"] = "How do I turn off the red glow on my frames?"
L["FAQ_GLOW_A"] = "On the \"%s\" page: \"%s\" for the red glow when something is on you, \"%s\" for the pulse on your player frame while you attack."
L["FAQ_TRACKER_Q"] = "Can I get the old quest tracker back?"
L["FAQ_TRACKER_A"] = "Yes. On the \"%s\" page, \"%s\" picks its look, Classic Era's quest watch among them."
L["FAQ_PLATES_Q"] = "How do I make nameplates bigger?"
L["FAQ_PLATES_A"] = "Their size is the game's own, under \"%s\" in its Options. \"%s\" on the \"%s\" page changes only the name."
L["FAQ_MOVE_Q"] = "Can I move windows?"
L["FAQ_MOVE_A"] = "Yes, out of combat. Hover a window's title bar and click its lock, then drag it by the title. Or place windows in edit mode under \"%s\". The red button beside the lock puts a window back where it opens by default."
L["FAQ_MOVERS_Q"] = "Why can my window mover move some windows but not others?"
L["FAQ_MOVERS_A"] = "The character sheet and other game windows are the game's own in the 1.x look, so window movers can move them; \"%s\" in the options leaves them fully to such an addon. Our spellbook and quest log are built by us, as the game has none shaped like Era's, and window movers only move windows on their own list. Ours move with the lock on their title bar, or in edit mode."
L["FAQ_SETTING_Q"] = "Can I change how something looks or works?"
L["FAQ_SETTING_A"] = "Most likely. Nearly every piece can be turned off or tuned: type a word into the \"%s\" box at the top left of this window. If you cannot find it, ask on GitHub or CurseForge."
L["FAQ_SETTING_PIECE_A"] = "Most likely. Every switch this piece has is on its \"%s\" tab. If you cannot find it, ask on GitHub or CurseForge."
L["FAQ_FOREVER_Q"] = "Can I keep Forever's own look for some parts?"
L["FAQ_FOREVER_A"] = "Yes. Every classic piece has its own switch in this window; turn it off and Forever's own comes back. A few changes need a reload, and a popup asks for it."
L["FAQ_OTHER_ADDON_Q"] = "Can you make %s work with another addon?"
L["FAQ_OTHER_ADDON_A"] = "Tell us which one on GitHub or CurseForge and we will take a look. When two addons restyle the same part of the screen, turning that part off here usually lets both work."
L["FAQ_LFG_RETAIL_A"] = "1.x had none, so it is off the micro menu. Click the eye on the minimap, or press the group finder key (%s). To bring the button back, uncheck \"%s\" under \"%s\"."
L["FAQ_REAGENT_RETAIL_A"] = "It stands in the key ring's old slot, at the end of your bags. For a slot like the other bags, pick \"%s\"."
L["FAQ_OWNLOOK_Q"] = "Can I keep the game's own look for some parts?"
L["FAQ_OWNLOOK_A"] = "Yes. Every classic piece has its own switch in this window; turn it off and the game's own comes back. A few changes need a reload, and a popup asks for it."
L["FAQ_RETAILBUTTONS_Q"] = "Where are my %s, %s and %s buttons?"
L["FAQ_RETAILBUTTONS_A"] = "1.x had none, so they are off the micro menu. Click their icons on the minimap, or press the key for %s (%s) or %s (%s). To bring a button back, uncheck it under \"%s\"."
L["FAQ_SUITE_Q"] = "What is ClassicUI Forever?"
L["FAQ_SUITE_A"] = "The full addon suite this piece comes from: the whole 1.x look, from the bars and bags to unit frames, maps and windows. Only one of them runs at a time, so for more than this piece, get the full ClassicUI Forever and turn off what you do not want."
L["FAQ_SUITE_PICKER_A"] = "The full addon suite this color picker was first made for: the whole 1.x look, from the bars and bags to unit frames, maps and windows, with this color picker built in. Only one of them runs at a time, so for both, get the full ClassicUI Forever."
L["FAQ_MICRO_KEY_A"] = "1.x had none, so it is off the micro menu. Press its key (%s). To bring the button back, uncheck \"%s\" under \"%s\"."
L["FAQ_MICRO_OFF_A"] = "1.x had none, so it is off the micro menu. To bring the button back, uncheck \"%s\" under \"%s\"."
L["FAQ_RETAILBUTTONS_KEY_A"] = "1.x had none, so they are off the micro menu. Press the key for %s (%s) or %s (%s). To bring a button back, uncheck it under \"%s\"."
L["SUPPORT_CAPTION"] = "Thank you for using %s."
L["SUPPORT_FEEDBACK_HEAD"] = "Feedback"
L["SUPPORT_FEEDBACK"] = "Bug reports, ideas and any other feedback are always welcome. Before you write one, please press %s and paste what it gives you into your report: your settings, game build and other addons."
L["SUPPORT_POST"] = "Then pick where to post. The buttons copy the address to paste into your browser."
L["SUPPORT_MORE_HEAD"] = "You may also like"
L["SUPPORT_MORE"] = "EasyFind, also from us: a command palette for the game. Type what you want and do it right from the results: open a window or setting, mount up, cast a spell or find a place on the map."
L["SUPPORT_MORE_BUTTON"] = "EasyFind on CurseForge"
L["SUPPORT_SUITE_BUTTON"] = "ClassicUI Forever on CurseForge"
L["SUPPORT_DONATE_HEAD"] = "Support the addon"
L["SUPPORT_DONATE"] = "%s is free. If you would like to support it, you can do so through Buy Me a Coffee."
L["SUPPORT_DONATE_BUTTON"] = "Buy Me a Coffee"

-- Era's interface size (Options/EraScale.lua).
L["ERASCALE_OFFER"] = "Classic Era draws its interface larger than Forever does by default. Switch to Era's size, with the classic-sized bars? The interface reloads. The game's %s setting changes the size any time."
L["ERASCALE_GIVEN_BACK"] = "Interface size set back. Looks different than you expected? Click %s."
L["ERASCALE_HELP"] = "The interface size went back to the one from before the classic layout changed it, or to the game's automatic size. If it still looks too big or too small, set it under %s in the game's Options: uncheck \"%s\" for the automatic size, or move its slider."
L["ERASCALE_OPEN_SETTINGS"] = "Game options"
L["ERASCALE_SWITCH"] = "Use Era's size"
L["ERASCALE_ASK"] = "Your interface is at a different size than Classic Era's on this screen. Switch to Era's size, with the classic-sized bars? The game's %s setting changes it any time."
L["ERASCALE_KEEP"] = "Keep my size"
